pub fn terrane_platform_compress(format: String, data: Vec<u8>, level: terrane_int_support::Int, deterministic: bool) -> TerranePlatformResult { terrane_platform_support::compress(&format, &data, terrane_platform_i128!(level, "compression level"), deterministic) }
pub fn terrane_platform_decompress(format: String, data: Vec<u8>, output: terrane_int_support::Int, ratio: terrane_int_support::Int, work: terrane_int_support::Int) -> TerranePlatformResult { terrane_platform_support::decompress(&format, &data, terrane_platform_i128!(output, "decompression output limit"), terrane_platform_i128!(ratio, "decompression ratio limit"), terrane_platform_i128!(work, "decompression work limit")) }
